html:
{%- macro emp(e) -%}{{ (frappe.db.get_value("Employee", e, "employee_name") or e) if e else "" }}{%- endmacro -%}
{%- macro dt(v) -%}{{ frappe.format(v, {"fieldtype": "Date"}) if v else "" }}{%- endmacro -%}
{%- macro qty(v) -%}{{ ("%g" | format(v)) if v else "" }}{%- endmacro -%}
{%- macro box(on) -%}<span class="cb">{% if on %}X{% endif %}</span>{%- endmacro -%}
{%- set ref = doc.qc_inspection or doc.asset_inspection or doc.housekeeping_inspection -%}
<style>
	.ncr { font-family: Arial, Helvetica, sans-serif; color: #000; font-size: 11px; }
	.print-format .ncr td, .print-format .ncr th, .ncr td, .ncr th { padding: 3px 6px !important; vertical-align: top; line-height: 1.25; }
	.ncr table { width: 100%; border-collapse: collapse; table-layout: fixed; }
	.ncr .hdr td { vertical-align: middle; font-size: 9px; }
	.ncr h1 { font-size: 22px; font-weight: bold; text-align: center; margin: 6px 0 4px 0; padding-bottom: 3px; border-bottom: 1px solid #555; }
	.ncr .frame { border: 2px solid #000; margin-top: 8px; }
	.ncr .info td { border: 1px solid #000; height: 22px; vertical-align: middle; }
	.ncr .info .lbl { text-align: right; font-weight: bold; width: 19%; }
	.ncr .sec { font-weight: bold; }
	.ncr .text td.tb { border-bottom: 1px solid #000; height: 62px; }
	.ncr .text td.tb.last { border-bottom: none; }
	/* Tables inside the description (inspection findings) keep normal rows */
	.ncr .body table { width: 100%; table-layout: auto; margin-top: 3px; }
	.ncr .body table td, .ncr .body table th { border: 1px solid #999; height: auto; padding: 1px 4px !important; font-size: 10px; }
	.ncr .text .body { margin-top: 2px; }
	.ncr .text .body p { margin: 0 0 3px 0; }
	.ncr .cb { display: inline-block; width: 10px; height: 10px; border: 1px solid #000; line-height: 10px; text-align: center; font-size: 9px; font-weight: bold; vertical-align: middle; margin-left: 6px; }
	.ncr .disp td { vertical-align: middle; }
	.ncr .r { text-align: right; }
	.ncr .dash td { border-bottom: 1px dotted #000; height: 18px; vertical-align: bottom; }
	.ncr .rule { border-top: 2px solid #000; }
	.ncr .u { border-bottom: 1px solid #000; display: inline-block; min-width: 190px; }
	.ncr .foot { margin-top: 6px; font-size: 9px; page-break-inside: avoid; }
	.ncr .foot td { vertical-align: top; }
	.ncr .crit td { vertical-align: middle; height: 20px; }
	.ncr .note { font-size: 9px; color: #333; }
</style>
<div class="ncr">
	<table class="hdr">
		<tr>
			<td style="width:28%">355 Gus Hipp Blvd.<br>Rockledge, FL 32955</td>
			<td style="width:44%; text-align:center"><img src="{{ frappe.utils.get_url('/assets/hse/images/psif_logo.jpg') }}" style="height:52px"></td>
			<td style="width:28%; text-align:right">Tel: (321) 636-0085<br><b>www.psifla.com</b></td>
		</tr>
	</table>
		<h1>{{ _("QM-104 Rework Report") }}</h1>

	<table class="frame info">
		<tr>
			<td class="lbl">{{ _("DATE:") }}</td><td>{{ dt(doc.rework_date or doc.ncr_date) }}</td>
			<td class="lbl" style="width:21%">{{ _("REWORK NO.:") }}</td><td>{{ doc.rework_no or "" }}<span style="float:right; font-size:8px; color:#555">{{ doc.name }}</span></td>
		</tr>
		<tr>
			<td class="lbl">{{ _("INITIATOR:") }}</td><td>{{ doc.rw_initiator_name or doc.initiator_name or (frappe.db.get_value("User", doc.rw_initiator, "full_name") if doc.rw_initiator else "") or "" }}</td>
			<td class="lbl">{{ _("JOB NO.:") }}</td><td>{{ doc.rw_job_no or "" }}</td>
		</tr>
		<tr>
			<td class="lbl">{{ _("CONTRACT:") }}</td><td>{{ doc.rw_contract or "" }}</td>
			<td class="lbl">{{ _("Lot Quantity:") }}</td><td>{{ qty(doc.rw_lot_qty) }}</td>
		</tr>
		<tr>
			<td class="lbl">{{ _("DRAWING NO.:") }}</td><td>{{ doc.rw_drawing_no or "" }}</td>
			<td class="lbl">{{ _("Reject Quantity:") }}</td><td>{{ qty(doc.rw_reject_qty) }}</td>
		</tr>
		<tr>
			<td class="lbl">{{ _("SOURCE:") }}</td>
			<td colspan="3">{{ _(doc.rw_source) if doc.rw_source else "" }}{% if ref %}{{ " - " if doc.rw_source else "" }}{{ ref }}{% endif %}{% if doc.qc_unit %} ({{ _("QC Unit") }} {{ doc.qc_unit }}){% elif doc.asset %} ({{ _("Asset") }} {{ doc.asset }}){% endif %}</td>
		</tr>
	</table>

	{%- macro yn(v) -%}{{ _("YES") }} {{ box(v == "Yes") }}&nbsp;&nbsp;{{ _("NO") }} {{ box(v == "No") }}{%- endmacro -%}
	<table class="frame crit">
		<tr><td colspan="4"><span class="sec">{{ _("NCR CRITERIA EVALUATION (QM-104 §3.3):") }}</span><span class="note" style="float:right">{{ _("Any YES requires an NCR. All NO: rework, not an NCR.") }}</span></td></tr>
		<tr>
			<td style="width:36%">{{ _("Results in scrap of a finished part") }}</td><td class="r" style="width:14%">{{ yn(doc.rw_crit_scrap) }}</td>
			<td style="width:36%">{{ _("Affects a customer requirement, safety or ship date") }}</td><td class="r">{{ yn(doc.rw_crit_customer_safety) }}</td>
		</tr>
		<tr>
			<td>{{ _("Can't be reworked to drawing or spec (QM-144)") }}</td><td class="r">{{ yn(doc.rw_crit_cannot_rework) }}</td>
			<td>{{ _("Supplier caused or suspected counterfeit (QM-134 / QM-310)") }}</td><td class="r">{{ yn(doc.rw_crit_supplier) }}</td>
		</tr>
		<tr><td colspan="4" class="note">{{ _("Evaluated By:") }} {{ (frappe.db.get_value("User", doc.rw_evaluated_by, "full_name") if doc.rw_evaluated_by else "") or "" }}&nbsp;&nbsp;&nbsp;{{ _("Date:") }} {{ dt(doc.rw_evaluated_on) if doc.rw_evaluated_on else "" }}{% if doc.escalated_to %}&nbsp;&nbsp;&nbsp;<b>{{ _("Escalated to NCR {0}").format(doc.escalated_to) }}</b>{% endif %}</td></tr>
	</table>

	<table class="frame text">
		<tr><td class="tb"><span class="sec">{{ _("QUALITY REQUIREMENT NOT MET:") }}</span>
			<div class="body">{% if doc.subject %}<b>{{ doc.subject }}</b>{% endif %}{{ doc.rw_requirement or doc.details or "" }}</div></td></tr>
		<tr><td class="tb"><span class="sec">{{ _("CAUSE:") }}</span><div class="body">{{ doc.rw_cause or "" }}</div></td></tr>
		<tr><td class="tb last"><span class="sec">{{ _("REWORK PERFORMED:") }}</span><div class="body">{{ doc.rw_rework_performed or "" }}</div></td></tr>
	</table>

	<table class="frame">
		<tr><td colspan="2" style="padding:0 !important">
			<table>
				<tr><td colspan="3"><span class="sec">{{ _("VERIFICATION OF REWORK:") }}</span></td></tr>
				<tr>
					<td style="width:50%">{{ _("QUALITY VERIFICATION:") }}</td>
					<td style="width:25%; text-align:right">{{ _("ACCEPT") }} {{ box(doc.rw_quality_verification == "Accept") }}</td>
					<td class="r" style="padding-right:30px !important">{{ _("REJECT") }} {{ box(doc.rw_quality_verification == "Reject") }}</td>
				</tr>
				<tr><td colspan="3" style="padding-top:8px !important; height:30px">{{ _("Comments:") }} {{ doc.rw_verification_comments or "" }}</td></tr>
			</table>
		</td></tr>
		<tr><td colspan="2" style="border-top:1px solid #000; padding:0 !important">
			<table>
				<tr><td style="width:69%; height:30px; vertical-align:middle">{{ _("Inspected By:") }} {{ emp(doc.rw_inspected_by) }}</td><td style="vertical-align:middle">{{ _("Date:") }} {{ dt(doc.rw_inspected_date) }}</td></tr>
				<tr><td style="height:30px; vertical-align:middle">{{ _("Approved By:") }} {{ emp(doc.rw_approved_by) }}</td><td style="vertical-align:middle">{{ _("Date:") }} {{ dt(doc.rw_approved_date) }}</td></tr>
			</table>
		</td></tr>
		{%- if doc.escalated_to %}
		<tr><td colspan="2" style="border-top:1px solid #000"><span class="sec">{{ _("ESCALATED TO NCR:") }}</span> {{ doc.escalated_to }}{% set nno = frappe.db.get_value("Nonconformance Report", doc.escalated_to, "ncr_no") %}{% if nno %} ({{ _("NCR No.") }} {{ nno }}){% endif %}</td></tr>
		{%- endif %}
	</table>

	<table class="foot">
		<tr>
			<td style="width:30%"></td>
			<td style="width:40%; text-align:center">{{ _("QM-104 Rework Report") }}<br><i>{{ _("Printed copies of this form are uncontrolled") }}</i></td>
			<td style="width:30%; text-align:right">{{ _("Rev. 3: 10/26") }}</td>
		</tr>
	</table>
</div>
